try:
    print('>>> f = map')
    print('>>> x = 1j')
    print('>>> y = frozenset()')
    print('>>> f(x, y)')
    f = map
    x = 1j
    y = frozenset()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
